INSERT INTO nw_chat_session_attachments(
  id, tenant_id, session_id, name, input_path, size, sha256, body_format, created_at, expires_at
) VALUES (
  CAST(#{id} AS uuid), CAST(#{tenantId} AS bigint), #{sessionId}, #{name}, #{inputPath},
  #{size}, #{sha256}, 'bytea.v1', #{createdAt}, #{expiresAt}
)
ON CONFLICT (id) DO NOTHING
